import * as React from "react"
import { Link } from "gatsby"
import { GatsbyImage, getImage } from "gatsby-plugin-image"
import { faAngleRight } from "@fortawesome/free-solid-svg-icons/faAngleRight"
import { faLongArrowAltRight } from "@fortawesome/free-solid-svg-icons/faLongArrowAltRight"
import { faFilePdf } from "@fortawesome/free-solid-svg-icons/faFilePdf"
import { FaIcon } from "./FaIcon"
import QuoteBlock from "./QuoteBlock"

const ServiceDetails = ({ description, sidebar, title, image, location, dataItem = [] }) => {
  const listMenu = sidebar.map((item, i) => (
    <li key={i} className={location.pathname.includes(item.href) ? "active" : ""}>
      <Link to={item.href} aria-current={"page"}>
        {item.title}
        {location.pathname.includes(item.href) && (
          <FaIcon
            fill={"rgb(34, 34, 34)"}
            className="icon"
            width={20}
            height={20}
            icon={faAngleRight}
            style={{
              float: "right",
              fontSize: "20px",
              marginTop: "2px",
              right: "15px",
              top: "18px",
              color: "#222222",
            }}
          />
        )}
      </Link>
    </li>
  ))

  const listDownloads = sidebar
    .filter(e => e.downloads != null && location.pathname.includes(e.href))
    .map(({ downloads }) =>
      downloads.map(({ publicURL, name, ext }) => (
        <div className="broucher-item">
          <a href={publicURL} target="_blank" rel="noopener noreferrer" >
            <FaIcon
              fill={"rgb(255, 255, 255)"}
              className="icon"
              width={25}
              height={25}
              icon={faFilePdf}
              style={{
                left: "14px",
                lineHeight: "30px",
                position: "absolute",
                textAlign: "center"
              }}
            />
            <div style={{ fontSize: '12px' }}>
              {name}
              {ext}</div>
            <FaIcon
              fill={"rgb(255, 255, 255)"}
              className="icon"
              width={20}
              height={20}
              icon={faLongArrowAltRight}
              style={{
                float: "right",
                fontSize: "20px",
                marginTop: "5px",
                right: "15px",
                top: "18px",
                color: "#fff",
                position: 'absolute'
              }}
            />
          </a>

        </div>
      )),
    )

  const listData = dataItem
    .map(({ title, description }, i) =>
      <div className="audit-text" key={'content_' + i} >
        <h3>{title}</h3>
        <div
          dangerouslySetInnerHTML={{
            __html: description,
          }}
        ></div>
      </div>
    )


  return (
    <section className="construct-single-service-area section_100">
      <div className="container">
        <div className="row">
          <div className="col-md-4">
            <div className="single-service-left">
              <div className="single-service-widget">
                <ul>{listMenu}</ul>
              </div>
              {sidebar.filter(
                e => e.downloads != null && location.pathname.includes(e.href),
              ).length > 0 && (
                  <div className="single-service-widget">
                    <div className="widget-title">
                      <h3>Descargas</h3>
                      <div className="title-line"></div>
                    </div>
                    {listDownloads}
                  </div>
                )}
              <div className="single-service-widget">
                <div className="widget-title">
                  <h3>Solicitar presupuesto</h3>
                  <div className="title-line"></div>
                </div>
                <QuoteBlock />
              </div>
            </div>
          </div>
          <div className="col-md-8">
            <div className="single-service-right">
              <div className="service-banner">
                <GatsbyImage image={getImage(image)} alt="" />
              </div>
              <div className="audit-text">
                <h3>{title}</h3>
                <div
                  dangerouslySetInnerHTML={{
                    __html: description,
                  }}
                ></div>
              </div>
              {listData}
            </div>
          </div>
        </div>
      </div>
    </section>
  )
}

export default ServiceDetails
